require __DIR__.'/../../public/api/_bootstrap.php';require __DIR__.'/../../public/api/_planner_mutations.php';$pdo=cssv_db();cssv_planner_ensure($pdo);$user=cssv_pro_id($argv[2]??null);$attempt=cssv_pro_id($argv[3]??null);cssv_learning_attempt($pdo,$attempt,$user);
