 $pdo->prepare('INSERT INTO mpt_sessions(id,mock_id,starts_at,ends_at) VALUES(?,?,?,?)')->execute([$session,$mock,$now,$future]);$pdo->prepare('INSERT INTO mpt_applications(id,application_code,user_id,mock_id,session_id,roll_number,applied_at) VALUES(?,?,?,?,?,?,?)')->execute([$application,$code,$user,$mock,$session,'000000000001',$now]);$ids=[];
 foreach([1,2] as $number){$id=cssv_uuid_v4();$pdo->prepare("INSERT INTO mpt_attempts(id,application_id,attempt_no,user_id,mock_id,status,started_at,expires_at,submitted_at,active_session_id,score,total_marks) VALUES(?,?,?,?,?,'SUBMITTED',?,?,?,'TEST ONLY',?,100)")->execute([$id,$application,$number,$user,$mock,$now,$future,$now,$number===1?30:80]);$ids[]=$id;}echo json_encode(['ids'=>$ids,'mock'=>$mock]);
}elseif(in_array($argv[1],['release','void'],true)){$id=cssv_pro_id($argv[4]??null);if($argv[1]==='release')$pdo->prepare("UPDATE mpt_mocks SET results_release_policy='IMMEDIATE_SCORE' WHERE id=? AND title='TEST ONLY planner source'")->execute([$id]);else $pdo->prepare('UPDATE mpt_attempts SET voided_at=NOW() WHERE id=? AND user_id=?')->execute([$id,$user]);}
